package com.example.bible.data

/** Вопрос брейн-ринга: устойчивый номер, чтобы помнить уже сыгранные. */
internal data class BrainRingFact(
    val id: String,
    val emoji: String,
    val prompt: String,
    val correct: String,
    val wrong: List<String>,
)

internal object BrainRingBank {
    const val SIZE = 1000
    val all: List<BrainRingFact> = buildList {
        addAll(part0())
        addAll(part1())
        addAll(part2())
        addAll(part3())
        addAll(part4())
        addAll(part5())
        addAll(part6())
        addAll(part7())
        addAll(part8())
        addAll(part9())
        addAll(part10())
        addAll(part11())
        addAll(part12())
        addAll(part13())
        addAll(part14())
        addAll(part15())
        addAll(part16())
        addAll(part17())
        addAll(part18())
        addAll(part19())
        addAll(part20())
        addAll(part21())
        addAll(part22())
        addAll(part23())
        addAll(part24())
    }

    init {
        check(all.size == SIZE)
        check(all.map { it.id }.toSet().size == SIZE)
        check(all.map { it.prompt }.toSet().size == SIZE)
        check(all.all { fact -> (fact.wrong + fact.correct).toSet().size == 3 })
    }
}

